pc_public_result <- function(result) {
  result$model <- NULL; result$survival_fit <- NULL
  result
}
pc_report <- function(result, tab, settings, history = character(), figure_svg = NULL) {
  esc <- htmltools::htmlEscape
  table_html <- function(d) {
    if (is.null(d) || !nrow(d)) return("")
    cells <- function(x) paste0("<td>", esc(ifelse(is.na(x), "—", as.character(x))), "</td>", collapse = "")
    paste0("<table><thead><tr>", paste0("<th>", esc(names(d)), "</th>", collapse = ""), "</tr></thead><tbody>", paste(apply(d, 1, function(x) paste0("<tr>", cells(x), "</tr>")), collapse = ""), "</tbody></table>")
  }
  paste0("<!doctype html><html><head><meta charset='utf-8'><title>RDataCraft analysis report</title><style>body{font:15px system-ui;color:#263b32;max-width:1100px;margin:48px auto;padding:0 24px}h1,h2{color:#247763}table{border-collapse:collapse;width:100%;margin:20px 0;font-size:13px}td,th{border:1px solid #d2ded6;padding:8px;text-align:left}th{background:#f1f5f2}p,li{line-height:1.6}@media print{body{margin:10mm}table{break-inside:auto}tr{break-inside:avoid}}</style></head><body><h1>", esc(settings$title), "</h1><p>RDataCraft 0.3 · ", esc(format(Sys.time(), tz = "UTC", usetz = TRUE)), "</p>", if (!is.null(figure_svg)) paste0("<div style='overflow:auto'>", figure_svg, "</div>"), "<h2>", esc(result$title), "</h2>", table_html(result$metrics), "<h2>Summary</h2>", table_html(result$summary), if (nrow(result$comparisons)) paste0("<h2>Comparisons</h2>", table_html(result$comparisons)), if (!is.null(result$at_risk)) paste0("<h2>Number at risk</h2>", table_html(result$at_risk)), if (!is.null(result$effects)) paste0("<h2>ANOVA table</h2>", table_html(result$effects)), if (!is.null(result$parameters)) paste0("<h2>Fit parameters</h2>", table_html(result$parameters)), if (!is.null(result$fit_status)) paste0("<h2>Fit status</h2>", table_html(result$fit_status)), if(!is.null(result$pca)) paste0("<h2>PCA explained variance</h2>",table_html(result$pca$scree),"<h2>PCA scores</h2>",table_html(result$pca$scores),"<h2>PCA loadings</h2>",table_html(result$pca$loadings),"<h2>PCA preprocessing</h2>",table_html(result$pca$preprocessing)), "<h2>Method and assumptions</h2><ul>", paste0("<li>", esc(result$notes), "</li>", collapse = ""), "</ul><h2>Source observations</h2>", table_html(tab), "<p>Table type: ", esc(settings$layout), ". Missing cells are shown as —. Numerical results were generated by ", esc(R.version.string), ". Tests are two-sided where applicable; confidence intervals are 95%. Export the matching SVG/PDF figure from the Graphs page.</p><p>This independent application is not affiliated with GraphPad.</p></body></html>")
}
